"use strict";(self.webpackChunkbast_docu=self.webpackChunkbast_docu||[]).push([[235],{88817:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"beta-26.2","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2","source":"@site/dadaprogressions-changelog/2026-07-04-beta-26.2.md","title":"DadaProgressions Beta 26.2","description":"Beta 26.2 adds a complete visual goal-editing workflow, makes configuration reloads transactional, and updates the bundled platform runtime.","date":"2026-07-04T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.2","title":"DadaProgressions Beta 26.2","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"nextItem":{"title":"DadaProgressions Beta 26.1","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.1"}},"content":"Beta 26.2 adds a complete visual goal-editing workflow, makes configuration reloads transactional, and updates the bundled platform runtime.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Visual goal editor\\n\\n`/dp admin editor` now opens a hierarchical editor for goals, composite criteria, modular filters, and prerequisite chains.\\n\\n- Rename, duplicate, enable, disable, or safely delete a goal.\\n- Change scope, period, event type, exact criterion targets, and the root `AND`/`OR` operator.\\n- Add or remove composite criteria.\\n- Add, edit, or remove global and per-criterion filters.\\n- Select achievement prerequisites and switch between `ALL` and `ANY` modes.\\n\\nNumeric fields use an in-GUI keypad. Materials, entities, worlds, game modes, damage causes, attribution values, and prerequisite goals use paginated selectors. Private chat remains available for free-form or custom values.\\n\\n## Safe writes, validation, and reload\\n\\nEvery visual edit is written atomically and checked against the complete goal set. If validation fails, DadaProgressions restores both the previous file and the previous runtime registry.\\n\\n`/dp admin validate` now re-reads every goal file without applying the candidate configuration. `/dp admin reload` is transactional: one invalid goal cannot replace a working runtime setup with a partial registry.\\n\\nValidation reports malformed YAML, invalid and duplicate IDs, incompatible filters and values, missing prerequisites, missing tiers, and prerequisite cycles.\\n\\n## DadaPlatform 26.2\\n\\nThe shaded runtime has been updated from DadaPlatform 26.0 to 26.2, updating the shared API used for chat, action bars, and MiniMessage formatting while preserving safe legacy fallbacks.\\n\\nThe platform runtime includes Folia-aware messaging and scheduler primitives. DadaProgressions Beta 26.2 does not yet declare full Folia support, because its recurring progression and storage tasks still use Bukkit scheduler APIs.\\n\\n## Integration notes\\n\\nThe Maven API version is now `beta-26.2`. Integrations use `com.dadaprogressions:dadaprogressions-api` and the `com.dadaprogressions.api.DadaProgressionsApi` Bukkit service.\\n\\nComposite goals can be updated through `addCriterionProgress(goalId, criterionId, player, amount)` or its UUID overload. Existing simple-goal integrations can continue using `addProgress`.\\n\\nInstall only `DadaProgressions-beta-26.2.jar` on the server. The API artifact belongs on an integration plugin\'s compile classpath with `provided` scope and must not be installed as a standalone plugin.\\n\\nThe release jar remains verified as Java 8 bytecode. The server must still run on the Java version required by its Minecraft/Spigot/Paper release."},{"id":"beta-26.1","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.1","source":"@site/dadaprogressions-changelog/2026-07-01-beta-26.1.md","title":"DadaProgressions Beta 26.1","description":"Beta 26.1 makes goals much more flexible and improves how progress notifications are delivered during busy sessions.","date":"2026-07-01T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.1","title":"DadaProgressions Beta 26.1","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"prevItem":{"title":"DadaProgressions Beta 26.2","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2"}},"content":"Beta 26.1 makes goals much more flexible and improves how progress notifications are delivered during busy sessions.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Modular goals\\n\\nGoals can now contain multiple criteria joined with `AND` or `OR`. Each criterion keeps its own progress, so a goal can ask players to complete several different tasks or let them choose between alternatives.\\n\\nFilters are available for materials, entities, worlds, game modes, permissions, commands, damage causes, and player attribution. Point rules can also assign fixed values or multipliers to specific actions.\\n\\nExisting single-type goals continue to work without changes.\\n\\n## Goal chains\\n\\nGoals can depend on other goals. A prerequisite may require the player to have completed a goal during the current period or at any point in the past.\\n\\nInvalid chains, missing prerequisites, and circular dependencies are reported when goals are loaded.\\n\\n## New community goal examples\\n\\nThe default configuration now includes four examples built with the modular goal engine:\\n\\n- `community_daily_supply_run`\\n- `community_weekly_beast_cleanup`\\n- `community_weekly_breeding_festival`\\n- `community_monthly_monument_project`\\n\\nAnimal breeding is now tracked automatically, including attribution for older server versions.\\n\\n## Clearer goal list\\n\\nGoal entries now show a short description of the actual objective. Their lore supports live progress and target placeholders, while the more technical details remain in the individual goal view.\\n\\nExtended state lore is hidden by default. It can be restored with `gui.list.goal-item.show-state-lore`.\\n\\n## Notification queues\\n\\nChat, action bar, title, and boss bar notifications now use separate queues. Repeated updates for the same goal are combined, preserving the starting value and total progress gained instead of filling the screen with one message per action.\\n\\nQueue timing, size, and channel limits can be configured globally, for a specific event, or for an individual goal.\\n\\n## Chat batching\\n\\nUpdates from several goals can be grouped into a single chat message while keeping their original order. The separator and maximum number of entries are configurable; setting `chat-batch.max-entries` to `0` includes every pending entry.\\n\\n```text\\nDaily Builder: 35 -> 45/128 (+10) | Community Weekly Build: 40 -> 50/5000 (+10)\\n```\\n\\nChat batching is enabled by default and can be overridden globally, per event, or per goal."}]}}')}}]);